local BeginnerCombatCellNode = Class("BeginnerCombatCellNode")
function BeginnerCombatCellNode:__init()
    self.btnActionGet   = nil
    self.btnActionFight = nil
end

function BeginnerCombatCellNode:__delete()
    self.btnActionGet   = nil
    self.btnActionFight = nil
    self.controller     = nil
end

---SetBtnCallBackGet
---设置单击回调函数(领取)
function BeginnerCombatCellNode:SetBtnCallBackGet(cb)
    self.btnActionGet = cb
end

---SetBtnCallBackGet
---设置单击回调函数(进入战斗)
function BeginnerCombatCellNode:SetBtnCallBackFight(cb)
    self.btnActionFight = cb
end

function BeginnerCombatCellNode:GetCellDt()
    return checkTable(self.cellDt)
end

function BeginnerCombatCellNode:GetTaskStatue()
    return checkInt(self:GetCellDt().taskStatus)
end

function BeginnerCombatCellNode:Awake()
    if isNull(self.CommonGoodsList.Env) then
        self.CommonGoodsList:Init()
    end
    SetButtonAction(self.FontStyleButton, function()--领取
        if self:GetTaskStatue() == Constants.GetStatus.Can then
            if type(self.btnActionGet) == 'function' then
                self.btnActionGet()
            end
        elseif self:GetTaskStatue() == Constants.GetStatus.Not then
            if type(self.btnActionFight) == 'function' then
                self.btnActionFight()
            end
        end
    end)
end

function BeginnerCombatCellNode:FreshBaseUI(data)
    self.cellDt = checkTable(data)

    self.TextTitle1.text   = tostring(data.name)
    self.TextTitle2.text   = tostring(data.name2)
    self.TextDescribe.text = tostring(data.descr)
    self.CommonGoodsList.Env:FreshBaseUI(parse_rewards(tostring(data.rewardId), tostring(data.rewardNum)))
    self.ImgIcon:LoadSprite(data.taskIcon)

    KTool.SetActive(self.Complete, self:GetTaskStatue() == Constants.GetStatus.Has)
    KTool.SetActive(self.FontStyleButton, self:GetTaskStatue() ~= Constants.GetStatus.Has)

    if self:GetTaskStatue() ~= Constants.GetStatus.Has then
        if self:GetTaskStatue() == Constants.GetStatus.Can then
            self.FontStyleButton:ResetFontStyle("B12", localize("领取"))
        else
            self.FontStyleButton:ResetFontStyle("B13", localize("前往"))
        end
    end
end

function BeginnerCombatCellNode:PlayFadeInAnim(index)
    if not isNull(self.AnimRoot) then
        CfUtils.PlayAnimator(self.AnimRoot, "Wait")
        CfUtils.PlayDelayShowAnimate(self.AnimRoot, 1, (index or 1) * 0.1)
    end
end

function BeginnerCombatCellNode:PlayInitAnim()
    if not isNull(self.AnimRoot) then
        CfUtils.PlayAnimator(self.AnimRoot, "Go")
    end
end

function BeginnerCombatCellNode:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end

return BeginnerCombatCellNode